-- Desliga o paralelismo automatico do Autonomous DB para esta sessao.
-- Mesmo motivo do 02a: evita o ORA-12839 ao rodar varios MERGE seguidos.
ALTER SESSION DISABLE PARALLEL DML;
ALTER SESSION DISABLE PARALLEL QUERY;

-- ============================================================
-- 02b. POPULAR TB_UNIDADE_SAUDE (todos os CNES da coorte de 45.416 casos)
-- Usa nome real para os 20 hospitais ja confirmados no Localizador do site,
-- o mesmo padrao de placeholder que voces ja usaram para os demais, e o
-- municipio sentinela 'Fora do Estado de SP' para unidades fora do estado.
-- ============================================================

MERGE INTO TB_UNIDADE_SAUDE tgt USING (SELECT '0000582' AS COD_CNES, 'Unidade CNES 0000582 (nome a confirmar via API CNES)' AS NOME_UNIDADE, ID_MUNICIPIO FROM TB_MUNICIPIO WHERE NOME_MUNICIPIO = 'Fora do Estado de SP') src ON (tgt.COD_CNES = src.COD_CNES) WHEN NOT MATCHED THEN INSERT (COD_CNES, NOME_UNIDADE, ENDERECO, ID_MUNICIPIO) VALUES (src.COD_CNES, src.NOME_UNIDADE, 'Endereco a confirmar via API CNES', src.ID_MUNICIPIO);
